<?php
require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/integrations.php';require_once __DIR__.'/lib/email_api_mailer.php';require_once __DIR__.'/lib/smtp_mailer.php';
if($_SERVER['REQUEST_METHOD']!=='POST'||!verifyCsrf($_POST['csrf']??'')){http_response_code(403);exit('Invalid request.');}$pdo=db();$user=currentUser();$batchId=(int)($_POST['batch_id']??0);$candidateId=trim((string)($_POST['candidate_id']??''));
$stmt=$pdo->prepare("SELECT er.id,er.email,er.status,ii.id invitation_id,ii.html_snapshot,eb.subject,eb.profile_id,wp.job_id FROM email_recipients er JOIN email_batches eb ON eb.id=er.batch_id LEFT JOIN wishlist_profiles wp ON wp.id=eb.profile_id LEFT JOIN interview_invitations ii ON ii.email_recipient_id=er.id WHERE er.batch_id=? AND er.candidate_id=? AND eb.user_id=? LIMIT 1");$stmt->execute([$batchId,$candidateId,$user['id']]);$row=$stmt->fetch();
try{if(!$row||$row['status']!=='failed'||empty($row['html_snapshot']))throw new RuntimeException('This failed scheduling email cannot be resent.');$api=integrationConfig('email_api');if(($api['status']??'')!=='configured')$api=['status'=>'configured','url'=>'https://hrms-api.nonceblox.com/api/emails/send-multi-recipient'];$testing=integrationConfig('email_testing');$testEmail=trim((string)($testing['email']??'kishan.sharma@nonceblox.com'));$targets=[$row['email']];if((!array_key_exists('enabled',$testing)||!empty($testing['enabled']))&&filter_var($testEmail,FILTER_VALIDATE_EMAIL)&&strcasecmp($testEmail,$row['email'])!==0)array_unshift($targets,$testEmail);foreach($targets as $target)emailApiSendHtml($api,[$target],$target===$row['email']?$row['subject']:'[TEST COPY] '.$row['subject'],$row['html_snapshot']);$pdo->beginTransaction();$pdo->prepare("UPDATE email_recipients SET status='sent',sent_at=NOW(),error_text=NULL WHERE id=?")->execute([$row['id']]);$pdo->prepare("UPDATE interview_invitations SET status='awaiting_confirmation',sent_at=NOW() WHERE id=?")->execute([$row['invitation_id']]);$pdo->prepare("UPDATE candidates SET stage='Interview' WHERE id=? AND job_id=?")->execute([$candidateId,$row['job_id']]);$pdo->prepare("INSERT INTO interview_invite_locks(profile_id,candidate_id,batch_id,active,locked_at) VALUES(?,?,?,1,NOW()) ON DUPLICATE KEY UPDATE batch_id=VALUES(batch_id),active=1,locked_at=NOW(),reset_at=NULL,reset_by=NULL")->execute([$row['profile_id'],$candidateId,$batchId]);$counts=$pdo->prepare("SELECT COUNT(*) total,SUM(status='sent') sent FROM email_recipients WHERE batch_id=?");$counts->execute([$batchId]);$count=$counts->fetch();$pdo->prepare("UPDATE email_batches SET status=? WHERE id=?")->execute([(int)$count['sent']===(int)$count['total']?'sent':'partial',$batchId]);$pdo->prepare("INSERT INTO audit_events(user_id,action,entity_type,entity_id,metadata_json) VALUES(?,'interview.invitation_resent','candidate',?,?)")->execute([$user['id'],$candidateId,json_encode(['batch_id'=>$batchId,'outcome'=>'success'])]);$pdo->commit();header('Location: interview_batch.php?id='.$batchId.'&action_done=resend');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();header('Location: interview_batch.php?id='.$batchId.'&error='.rawurlencode($e->getMessage()));}
